arguments.file_text:
.channel-item {
    padding: 8px 12px;
    cursor: pointer;
    border-left: 3px solid transparent;
    transition: background-color 0.15s;
}

.channel-item:hover {
    background-color: rgba(255, 255, 255, 0.08);
}

.channel-item.active {
    background-color: rgba(255, 255, 255, 0.12);
    border-left-color: #5865f2;
}

.channel-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.channel-name {
    font-weight: 600;
    font-size: 0.95rem;
    color: #dcddde;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.active .channel-name {
    color: #fff;
}

.unread-badge {
    background-color: #ed4245;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 1px 6px;
    border-radius: 9px;
    min-width: 18px;
    text-align: center;
    flex-shrink: 0;
}

.channel-description {
    font-size: 0.78rem;
    color: #8e9297;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.message-input-area {
    display: flex;
    gap: 8px;
    padding: 12px 16px;
    background-color: #40444b;
    border-top: 1px solid #2f3136;
    align-items: flex-end;
}

.message-textarea {
    flex: 1;
    resize: none;
    border: none;
    background-color: #40444b;
    color: #dcddde;
    font-size: 0.95rem;
    padding: 8px 12px;
    border-radius: 8px;
    outline: none;
    font-family: inherit;
    background-color: #383a40;
    min-height: 20px;
    max-height: 120px;
}

.message-textarea::placeholder {
    color: #72767d;
}

.send-button {
    background-color: #5865f2;
    color: #fff;
    border: none;
    border-radius: 6px;
    padding: 8px 16px;
    font-weight: 600;
    cursor: pointer;
    font-size: 0.9rem;
    white-space: nowrap;
    transition: background-color 0.15s;
}

.send-button:hover:not(:disabled) {
    background-color: #4752c4;
}

.send-button:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

.message-bubble {
    padding: 6px 16px;
    position: relative;
    transition: background-color 0.1s;
    border-radius: 4px;
}

.message-bubble.hovered {
    background-color: rgba(0, 0, 0, 0.15);
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
}

.author {
    font-weight: 600;
    color: #fff;
    font-size: 0.95rem;
}

.timestamp {
    font-size: 0.75rem;
    color: #72767d;
}

.message-content {
    color: #dcddde;
    font-size: 0.95rem;
    line-height: 1.4;
    margin-top: 2px;
    white-space: pre-wrap;
    word-break: break-word;
}

.reactions-row {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 4px;
}

.reaction-badge {
    background-color: rgba(88, 101, 242, 0.15);
    border: 1px solid rgba(88, 101, 242, 0.3);
    color: #dcddde;
    border-radius: 6px;
    padding: 2px 8px;
    font-size: 0.82rem;
    cursor: pointer;
    transition: background-color 0.15s;
}

.reaction-badge:hover {
    background-color: rgba(88, 101, 242, 0.3);
}

.thread-link {
    background: none;
    border: none;
    color: #00aff4;
    font-size: 0.82rem;
    cursor: pointer;
    padding: 2px 0;
    margin-top: 4px;
    font-weight: 500;
}

.thread-link:hover {
    text-decoration: underline;
}

.action-bar {
    position: absolute;
    top: -14px;
    right: 8px;
    display: flex;
    gap: 2px;
    background-color: #2f3136;
    border: 1px solid #202225;
    border-radius: 6px;
    padding: 2px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
    z-index: 10;
}

.action-button {
    background: none;
    border: none;
    color: #b9bbbe;
    font-size: 0.8rem;
    padding: 4px 8px;
    cursor: pointer;
    border-radius: 4px;
    white-space: nowrap;
    transition: background-color 0.15s, color 0.15s;
}

.action-button:hover {
    background-color: rgba(255, 255, 255, 0.08);
    color: #fff;
}

.emoji-picker-toggle {
    position: relative;
}

.emoji-picker {
    position: absolute;
    top: 100%;
    right: 0;
