@inject IJSRuntime JS

<div class="message-area">
    <div class="area-header">
        <h3># @ChannelName</h3>
        @if (!string.IsNullOrEmpty(ChannelDescription))
        {
            <span class="area-description">@ChannelDescription</span>
        }
    </div>

    <div class="message-list" @ref="_messageListRef" @onscroll="HandleScroll">
        @if (IsLoadingMore)
        {
            <div class="loading-indicator">Loading older messages…</div>
        }
        @foreach (var msg in Messages)
        {
            <MessageBubble Message="msg"
                           ReplyCount="GetReplyCount(msg.Id)"
                           OnOpenThread="OnOpenThread"
                           OnReact="OnReact" />
        }
    </div>

    <MessageInput Placeholder="@($"Message #{ChannelName}")"
                  ButtonLabel="Send"
                  OnSubmit="OnSendMessage" />
</div>

@code {
    [Parameter] public string ChannelName { get; set; } = string.Empty;
    [Parameter] public string ChannelDescription { get; set; } = string.Empty;
    [Parameter] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = new();
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback OnLoadOlderMessages { get; set; }

    private ElementReference _messageListRef;
    private bool _shouldScrollToBottom = true;
    private int _previousMessageCount;

    private int GetReplyCount(int messageId) =>
        ThreadReplyCounts.TryGetValue(messageId, out var count) ? count : 0;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await ScrollToBottom();
        }
        else if (_shouldScrollToBottom && Messages.Count > _previousMessageCount)
        {
            await ScrollToBottom();
        }
        _previousMessageCount = Messages.Count;
    }

    private async Task ScrollToBottom()
    {
        try
        {
            await JS.InvokeVoidAsync("chatScrollHelper.scrollToBottom", _messageListRef);
        }
        catch (JSException) { }
    }

    private async Task HandleScroll()
    {
        try
        {
            var scrollTop = await JS.InvokeAsync<double>("chatScrollHelper.getScrollTop", _messageListRef);
            _shouldScrollToBottom = false;
            if (scrollTop <= 1 && !IsLoadingMore)
            {
                await OnLoadOlderMessages.InvokeAsync();
            }
        }
        catch (JSException) { }
    }
}

