@page "/chat"
@layout ChatLayout
@rendermode InteractiveServer
@using sv_bcb9efd9975e4ba98d773abef29c3bae.Models
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<ChannelSidebar Channels="Channels"
                ActiveChannelId="SelectedChannel?.Id"
                OnChannelSelected="SelectChannel" />

<MessageArea ChannelName="@(SelectedChannel?.Name ?? "")"
             ChannelDescription="@(SelectedChannel?.Description ?? "")"
             Messages="Messages"
             ThreadReplyCounts="ThreadReplyCounts"
             IsLoadingMore="IsLoadingMore"
             OnSendMessage="SendMessage"
             OnOpenThread="OpenThread"
             OnReact="HandleReaction"
             OnLoadOlderMessages="LoadOlderMessages" />

@if (IsThreadOpen && ThreadRootMessage is not null)
{
    <ThreadPanel RootMessage="ThreadRootMessage"
                 ThreadMessages="ThreadMessages"
                 OnClose="CloseThread"
                 OnReply="SendThreadReply" />
}

@code {
    private List<Channel> Channels { get; set; } = [];
    private Channel? SelectedChannel { get; set; }
    private List<Message> Messages { get; set; } = [];
    private Dictionary<int, int> ThreadReplyCounts { get; set; } = new();
    private bool IsLoadingMore { get; set; }

    private bool IsThreadOpen { get; set; }
    private Message? ThreadRootMessage { get; set; }
    private List<Message> ThreadMessages { get; set; } = [];

    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        Channels = await ChatService.GetChannelsAsync();
        if (Channels.Count > 0)
        {
            await SelectChannel(Channels[0]);
        }
    }

    private async Task SelectChannel(Channel channel)
    {
        SelectedChannel = channel;
        Messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        await ChatService.MarkChannelReadAsync(channel.Id);
        BuildThreadReplyCounts();

        // Refresh channels to update unread counts
        Channels = await ChatService.GetChannelsAsync();
    }

    private async Task LoadOlderMessages()
    {
        if (SelectedChannel is null || IsLoadingMore) return;
        IsLoadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(SelectedChannel.Id, Messages.Count, PageSize);
        if (older.Count > 0)
        {
            Messages.InsertRange(0, older);
            BuildThreadReplyCounts();
        }
        IsLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        if (SelectedChannel is null) return;
        var msg = await ChatService.SendMessageAsync(SelectedChannel.Id, content, null);
        Messages.Add(msg);
    }

    private async Task OpenThread(int messageId)
    {
        ThreadRootMessage = Messages.FirstOrDefault(m => m.Id == messageId);
        if (ThreadRootMessage is null) return;
        ThreadMessages = await ChatService.GetThreadAsync(messageId);
        IsThreadOpen = true;
    }

    private void CloseThread()
    {
        IsThreadOpen = false;
        ThreadRootMessage = null;
        ThreadMessages = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (SelectedChannel is null || ThreadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(SelectedChannel.Id, content, ThreadRootMessage.Id);
        ThreadMessages.Add(reply);

        // Update reply count in main view
        ThreadReplyCounts[ThreadRootMessage.Id] = ThreadMessages.Count;
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Refresh messages to show updated reaction
        if (SelectedChannel is not null)
        {
            Messages = await ChatService.GetMessagesAsync(SelectedChannel.Id, 0, Messages.Count);
        }
    }

    private void BuildThreadReplyCounts()
    {
        ThreadReplyCounts.Clear();
        // Messages with ReplyToId set indicate they are replies to another message
        foreach (var msg in Messages.Where(m => m.ReplyToId.HasValue))
        {
            var rootId = msg.ReplyToId!.Value;
            ThreadReplyCounts.TryGetValue(rootId, out var count);
            ThreadReplyCounts[rootId] = count + 1;
        }
    }
}

window.chatScrollHelper = {
    scrollToBottom: function (element) {
        if (element) {
            element.scrollTop = element.scrollHeight;
        }
    },
    getScrollTop: function (element) {
        return element ? element.scrollTop : 0;
    }
};

